   112	                    throw ApiException.conflict("COUPON_EXHAUSTED", "coupon " + couponCode + " is exhausted");
   113	                }
   114	                discount = coupon.discountFor(subtotal);
   115	            }
   116	
   117	            locked.forEach((id, p) -> products.addReserved(id, quantityOf(items, id)));
   118	            if (couponCode != null) {
   119	                coupons.addUsed(couponCode, 1);
   120	            }
   121	            long id = orders.insert(userId, couponCode, subtotal, discount, subtotal - discount, now,
   122	                    Times.normalize(now.plus(paymentTtl)), lines);
   123	            String body = json(orders.find(id).orElseThrow());
   124	            idempotency.complete(IdempotencyService.SCOPE_CREATE_ORDER, idemKey, 201, body, location(id));
   125	            return new Written(201, body, id);
   126	        });
   127	    }
   128	
   129	    private static long quantityOf(List<ItemCommand> items, long productId) {
   130	        return items.stream().filter(i -> i.productId() == productId).mapToLong(ItemCommand::quantity).sum();
   131	    }
