   170	            case OK -> result.written();
   171	            case DECLINED -> throw new ApiException(HttpStatus.PAYMENT_REQUIRED, "PAYMENT_DECLINED",
   172	                    "payment for order " + orderId + " was declined");
   173	            case EXPIRED -> throw ApiException.invalidState("order " + orderId + " has expired");
   174	        };
   175	    }
   176	
   177	    // ---------------------------------------------------------------- cancel / refund (R7)
   178	
   179	    public String cancel(long orderId) {
   180	        Object result = tx.execute(s -> {
   181	            Order order = orders.lock(orderId).orElseThrow(() -> orderNotFound(orderId));
   182	            switch (order.status()) {
   183	                case PENDING_PAYMENT -> {
   184	                    if (!Times.now().isBefore(order.expiresAt())) {
   185	                        expiry.expire(order);
   186	                        return Boolean.FALSE;
   187	                    }
   188	                    releaser.releaseReservation(order);
   189	                    orders.updateStatus(order.id(), OrderStatus.CANCELLED);
   190	                }
   191	                case PAID -> {
   192	                    if (order.paymentId() != null) {
   193	                        gateway.refund(order.paymentId());
   194	                    }
   195	                    releaser.returnStock(order);
   196	                    orders.updateStatus(order.id(), OrderStatus.REFUNDED);
   197	                }
   198	                default -> throw ApiException.invalidState("order " + orderId + " is " + order.status());
   199	            }
   200	            return json(orders.find(order.id()).orElseThrow());
   201	        });
   202	        if (Boolean.FALSE.equals(result)) {
   203	            throw ApiException.invalidState("order " + orderId + " has expired");
   204	        }
   205	        return (String) result;
   206	    }
   207	
   208	    // ---------------------------------------------------------------- shipping (R8)
   209	
   210	    public String ship(long orderId) {
   211	        return transition(orderId, OrderStatus.PAID, OrderStatus.SHIPPED);
   212	    }
   213	
   214	    public String deliver(long orderId) {
   215	        return transition(orderId, OrderStatus.SHIPPED, OrderStatus.DELIVERED);
   216	    }
   217	
   218	    private String transition(long orderId, OrderStatus from, OrderStatus to) {
   219	        expiry.expireDue();
   220	        return tx.execute(s -> {
   221	            Order order = orders.lock(orderId).orElseThrow(() -> orderNotFound(orderId));
   222	            if (order.status() != from) {
   223	                throw ApiException.invalidState("order " + orderId + " is " + order.status());
   224	            }
   225	            orders.updateStatus(order.id(), to);
   226	            return json(orders.find(order.id()).orElseThrow());
   227	        });
   228	    }
   229	
   230	    // ---------------------------------------------------------------- reads (R3.5, R9)
   231	
   232	    public OrderResponse get(long orderId) {
   233	        expiry.expireDue();
   234	        return orders.find(orderId).map(OrderResponse::from).orElseThrow(() -> orderNotFound(orderId));
   235	    }
   236	
   237	    public record Page(List<OrderResponse> content, String nextCursor) {
   238	    }
   239	
   240	    public Page list(String userId, OrderStatus status, int size, OrderCursor cursor) {
   241	        expiry.expireDue();
   242	        List<Order> rows = orders.page(userId, status, cursor == null ? null : cursor.createdAt(),
   243	                cursor == null ? null : cursor.id(), size + 1);
   244	        boolean more = rows.size() > size;
   245	        List<Order> pageRows = more ? rows.subList(0, size) : rows;
   246	        String next = null;
   247	        if (more) {
   248	            Order last = pageRows.get(pageRows.size() - 1);
   249	            next = new OrderCursor(last.createdAt(), last.id()).encode();
   250	        }
   251	        return new Page(pageRows.stream().map(OrderResponse::from).toList(), next);
   252	    }
   253	
   254	    private static ApiException orderNotFound(long id) {
   255	        return ApiException.notFound("ORDER_NOT_FOUND", "order " + id + " not found");
   256	    }
   257	
   258	    private String json(Order order) {
   259	        try {
   260	            return mapper.writeValueAsString(OrderResponse.from(order));
   261	        } catch (JsonProcessingException e) {
   262	            throw new IllegalStateException(e);
   263	        }
   264	    }
   265	}
