package com.example.order.order;

import java.time.OffsetDateTime;
import java.util.ArrayList;
import java.util.Collection;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.jdbc.core.namedparam.MapSqlParameterSource;
import org.springframework.jdbc.core.namedparam.NamedParameterJdbcTemplate;
import org.springframework.stereotype.Repository;

@Repository
public class OrderRepository {

    private static final String COLS = "id, tenant_id, user_id, status, coupon_code, subtotal, discount, total_price, "
            + "created_at, expires_at, paid_at, payment_id";

    private static final RowMapper<Order> MAPPER = (rs, i) -> new Order(
            rs.getLong("id"), rs.getString("tenant_id"), rs.getString("user_id"),
            OrderStatus.valueOf(rs.getString("status")), rs.getString("coupon_code"), rs.getLong("subtotal"),
            rs.getLong("discount"), rs.getLong("total_price"), rs.getObject("created_at", OffsetDateTime.class),
            rs.getObject("expires_at", OffsetDateTime.class), rs.getObject("paid_at", OffsetDateTime.class),
            rs.getString("payment_id"), List.of());

    private final JdbcTemplate jdbc;
    private final NamedParameterJdbcTemplate named;

